package android.content;import java.util.*;public class SharedPreferences {final Map<String,Object> data=new HashMap<>();public String getString(String k,String value){return (String)data.getOrDefault(k,value);}public boolean getBoolean(String k,boolean value){return (Boolean)data.getOrDefault(k,value);}public Editor edit(){return new Editor();}public class Editor {public Editor putString(String k,String v){data.put(k,v);return this;}public Editor putBoolean(String k,boolean v){data.put(k,v);return this;}public void apply(){}}}
